import React, { useState } from "react";

function ApplicationsTable({ applications }) {
  const [selectedApp, setSelectedApp] = useState(null);

  const styles = {
    container: {
      background: "#fff",
      borderRadius: "12px",
      boxShadow: "0 3px 15px rgba(0,0,0,0.05)",
      overflowX: "auto",
      padding: "25px",
      marginBottom: "30px",
    },
    table: { width: "100%", borderCollapse: "collapse" },
    th: { textAlign: "left", fontSize: "13px", fontWeight: 600, padding: "12px 16px", color: "#475569", textTransform: "uppercase" },
    td: { padding: "14px 16px", fontSize: "14px", color: "#334155", borderTop: "1px solid #e2e8f0" },
    empty: { padding: "48px", textAlign: "center", fontSize: "16px", color: "#6B7280" },
    btn: { padding: "6px 12px", border: "none", borderRadius: "6px", cursor: "pointer", background: "#2563eb", color: "#fff" },
    modalOverlay: { position: "fixed", top:0, left:0, right:0, bottom:0, backgroundColor:"rgba(0,0,0,0.6)", display:"flex", justifyContent:"center", alignItems:"flex-start", paddingTop:"60px", zIndex:1000 },
    modal: { background:"#fff", width:"90%", maxWidth:"600px", borderRadius:"12px", padding:"24px", boxShadow:"0 8px 30px rgba(0,0,0,0.2)" },
    modalHeader: { display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:"20px" },
    modalTitle: { fontSize:"20px", color:"#1e293b" },
    closeBtn: { border:"none", background:"transparent", fontSize:"18px", cursor:"pointer" },
    detailItem: { marginBottom:"12px" },
    label: { fontWeight:"600", marginRight:"8px" },
  };

  if (applications.length === 0) {
    return <div style={styles.empty}>No applications received yet</div>;
  }

  return (
    <div style={styles.container}>
      <table style={styles.table}>
        <thead>
          <tr>
            {["Name", "E-mail Id", "Phone", "Resume", "Skill Set", "Actions"].map(col => (
              <th key={col} style={styles.th}>{col}</th>
            ))}
          </tr>
        </thead>
        <tbody>
          {applications.map((app, index) => (
            <tr key={index}>
              <td style={styles.td}>{app.name}</td>
              <td style={styles.td}>{app.email}</td>
              <td style={styles.td}>{app.phone}</td>
              <td style={styles.td}>
                {app.resume ? <a href={app.resume} target="_blank" rel="noreferrer">View PDF</a> : "NA"}
              </td>
              <td style={styles.td}>{app.skillset}</td>
              <td style={styles.td}>
                <button style={styles.btn} onClick={() => setSelectedApp(app)}>View Full Details</button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>

      {/* Modal for full details */}
      {selectedApp && (
        <div style={styles.modalOverlay}>
          <div style={styles.modal}>
            <div style={styles.modalHeader}>
              <h2 style={styles.modalTitle}>Application Details</h2>
              <button style={styles.closeBtn} onClick={() => setSelectedApp(null)}>×</button>
            </div>
            <div>
              <div style={styles.detailItem}><span style={styles.label}>Name:</span> {selectedApp.name}</div>
              <div style={styles.detailItem}><span style={styles.label}>Email:</span> {selectedApp.email}</div>
              <div style={styles.detailItem}><span style={styles.label}>Phone:</span> {selectedApp.phone}</div>
              <div style={styles.detailItem}><span style={styles.label}>Skill Set:</span> {selectedApp.skillset}</div>
              <div style={styles.detailItem}>
                <span style={styles.label}>Resume:</span> 
                {selectedApp.resume ? <a href={selectedApp.resume} target="_blank" rel="noreferrer">View PDF</a> : "NA"}
              </div>
              {Object.keys(selectedApp).map((key) => {
                if (!["name","email","phone","skillset","resume"].includes(key)) {
                  return <div key={key} style={styles.detailItem}><span style={styles.label}>{key}:</span> {selectedApp[key]}</div>;
                }
                return null;
              })}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default ApplicationsTable;
